#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="${ROOT_DIR}/.env"

rand() { openssl rand -hex 16; }

if [[ -f "$ENV_FILE" ]]; then
  echo ".env already exists at $ENV_FILE — skipping generation"
  exit 0
fi

CODELEARN_DB_PASS="$(rand)"
JUDGE0_DB_PASS="$(rand)"
ADMIN_PASS="$(rand)"
GOSHA_PASS="$(rand)"
APP_SECRET="$(openssl rand -hex 32)"

cat > "$ENV_FILE" <<EOF
# Generated by scripts/generate-env.sh
APP_SECRET_KEY=${APP_SECRET}
APP_DEBUG=true
APP_DOMAIN=localhost
APP_HOST=0.0.0.0
APP_PORT=8000

DATABASE_URL=postgresql://codelearn:${CODELEARN_DB_PASS}@127.0.0.1:5432/codelearn
CODELEARN_DB_USER=codelearn
CODELEARN_DB_PASS=${CODELEARN_DB_PASS}
CODELEARN_DB_NAME=codelearn

JUDGE0_DB_USER=judge0
JUDGE0_DB_PASS=${JUDGE0_DB_PASS}
JUDGE0_DB_NAME=judge0
JUDGE0_DB_HOST=127.0.0.1
JUDGE0_DB_PORT=5432

REDIS_URL=redis://127.0.0.1:6379/0
JUDGE0_REDIS_URL=redis://127.0.0.1:6379/1

JUDGE0_API_URL=http://127.0.0.1:2358
JUDGE0_API_TOKEN=
JUDGE0_PORT=2358
JUDGE0_RAILS_ENV=production

CODE_RUN_TIME_LIMIT=3
CODE_RUN_MEMORY_LIMIT=128000
CODE_RUN_OUTPUT_LIMIT=20000

INITIAL_ADMIN_USERNAME=admin
INITIAL_ADMIN_PASSWORD=${ADMIN_PASS}
INITIAL_ADMIN_EMAIL=admin@localhost

CREATE_DEMO_STUDENT=true
DEMO_STUDENT_USERNAME=gosha
DEMO_STUDENT_PASSWORD=${GOSHA_PASS}
DEMO_STUDENT_NAME=Гоша

# Optional one-time seed for Telegram bot settings (runtime config is in admin panel)
# TELEGRAM_BOT_ENABLED=false
# TELEGRAM_BOT_TOKEN=
# TELEGRAM_BOT_USERNAME=
# TELEGRAM_HTTP_PROXY=
# TELEGRAM_NOTIFY_ALL_SUBMISSIONS=false
EOF

chmod 600 "$ENV_FILE"
echo "Generated $ENV_FILE"
